# Warehouse Management Portal demo: English source -> (French, Arabic).
# Generate lib/js/i18n-strings.js with: python3 mkdict.py i18n/strings.py lib/js/i18n-strings.js
# Records stay as recorded (company names, addresses, product descriptions, audit change details):
# a warehouse system shows its data as it was entered, whatever the interface language.
SOURCE = 'en'
TARGETS = ('fr', 'ar')
MOUNT = '.navbar .container-fluid'
# Audit change details are not in the dictionary, so they stay as recorded.
CSS = 'html[lang="ar"] *{letter-spacing:0!important}.navbar .ci18n-switch{margin-inline-start:10px}html[dir=rtl] .ms-auto{margin-left:0!important;margin-right:auto!important}html[dir=rtl] .me-2{margin-right:0!important;margin-left:.5rem!important}html[dir=rtl] .text-end{text-align:left!important}html[dir=rtl] .dropdown-menu{text-align:right}'
EXTRA = '''
document.addEventListener('DOMContentLoaded', function () {
  if (!window.Chart || !window.CI18N) return;
  function tr(c) {
    if (!c.$ci18nSrc) c.$ci18nSrc = (c.data.labels || []).slice();
    c.data.labels = c.$ci18nSrc.map(function (x) { return CI18N.t(String(x)); });
    (c.data.datasets || []).forEach(function (d) { if (d.$src == null) d.$src = d.label; if (d.$src) d.label = CI18N.t(d.$src); });
  }
  Chart.register({ id: 'ci18n', beforeUpdate: tr });
  var all = function () { Object.values(Chart.instances || {}).forEach(function (c) { c.update(); }); };
  setTimeout(all, 0);
  CI18N.onChange(all);
});
'''
